from inimerge.merge import merge_layers, read_layer, render


def test_later_layer_wins():
    base = read_layer("[s]\na = 1\nb = 2\n")
    override = read_layer("[s]\nb = 3\n")
    assert merge_layers([base, override]) == {"s": {"a": "1", "b": "3"}}


def test_sections_are_added():
    merged = merge_layers([read_layer("[a]\nx = 1\n"), read_layer("[b]\ny = 2\n")])
    assert list(merged) == ["a", "b"]


def test_base_only_key_survives():
    merged = merge_layers([read_layer("[s]\nkeep = 1\n"), read_layer("[s]\nother = 2\n")])
    assert merged["s"]["keep"] == "1"


def test_render():
    assert render({"s": {"a": "1"}, "t": {"b": "2"}}) == "[s]\na = 1\n\n[t]\nb = 2\n"

